package com.tapeverify.copilot.service;

import com.tapeverify.copilot.entity.*; import com.tapeverify.copilot.repository.LoanRepository; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*; import org.springframework.stereotype.Service;
@Service public class ValidationServiceImpl implements ValidationService {
 private static final Set<String> US_STATES=Set.of("AL","AK","AZ","AR","CA","CO","CT","DE","FL","GA","HI","IA","ID","IL","IN","KS","KY","LA","MA","MD","ME","MI","MN","MO","MS","MT","NC","ND","NE","NH","NJ","NM","NV","NY","OH","OK","OR","PA","RI","SC","SD","TN","TX","UT","VA","VT","WA","WI","WV","WY","DC");
 private final LoanRepository loans; private final ValidationRules rules; public ValidationServiceImpl(LoanRepository loans,ValidationRules rules){this.loans=loans;this.rules=rules;}
 public List<ValidationException> validate(Loan loan) {List<ValidationException> e=new ArrayList<>(); required(e,loan,"borrowerName",loan.getBorrowerName(),"Borrower name is required");required(e,loan,"sourceLoanId",loan.getSourceLoanId(),"Loan ID is required");if(loan.getPrincipalAmount()==null)add(e,loan,"principalAmount","Original principal is required");else if(loan.getPrincipalAmount().compareTo(BigDecimal.ZERO)<=0)add(e,loan,"principalAmount","Principal amount must be greater than zero");if(loan.getCurrentBalance()==null)add(e,loan,"currentBalance","Current balance is required");else if(loan.getCurrentBalance().compareTo(BigDecimal.ZERO)<0)add(e,loan,"currentBalance","Current balance cannot be negative");else if(loan.getPrincipalAmount()!=null&&loan.getCurrentBalance().compareTo(loan.getPrincipalAmount())>0)add(e,loan,"currentBalance","Current balance cannot exceed original principal");if(loan.getInterestRate()==null)add(e,loan,"interestRate","Interest rate is required");else if(loan.getInterestRate().compareTo(rules.minRate())<0||loan.getInterestRate().compareTo(rules.maxRate())>0)add(e,loan,"interestRate","Interest rate must be between "+rules.minRate()+" and "+rules.maxRate());if(loan.getOriginationDate()==null)add(e,loan,"originationDate","Origination date is required");if(loan.getMaturityDate()==null)add(e,loan,"maturityDate","Maturity date is required");if(loan.getOriginationDate()!=null&&loan.getMaturityDate()!=null&&!loan.getMaturityDate().isAfter(loan.getOriginationDate()))add(e,loan,"maturityDate","Maturity date must be after origination date");required(e,loan,"paymentStatus",loan.getPaymentStatus(),"Payment status is required");if(loan.getPaymentStatus()!=null&&!rules.paymentStatuses().contains(loan.getPaymentStatus().toUpperCase()))add(e,loan,"paymentStatus","Invalid payment status");if(loan.getDaysPastDue()!=null&&loan.getDaysPastDue()>0&&"CURRENT".equalsIgnoreCase(loan.getPaymentStatus()))add(e,loan,"paymentStatus","Current status conflicts with days past due");if("CLOSED".equalsIgnoreCase(loan.getPaymentStatus())&&loan.getCurrentBalance()!=null&&loan.getCurrentBalance().compareTo(BigDecimal.ZERO)>0)add(e,loan,"paymentStatus","Closed loan cannot have positive balance");required(e,loan,"documentStatus",loan.getDocumentStatus(),"Document status is required");if(loan.getDocumentStatus()!=null&&!rules.documentStatuses().contains(loan.getDocumentStatus().toUpperCase()))add(e,loan,"documentStatus","Invalid document status");if(loan.getBorrowerState()!=null&&!US_STATES.contains(loan.getBorrowerState().toUpperCase()))add(e,loan,"borrowerState","State must be a valid US state or DC code");if(loan.getLastUpdatedAt()==null)add(e,loan,"lastUpdatedAt","Last updated timestamp is required");else if(loan.getLastUpdatedAt().isBefore(LocalDateTime.now().minusDays(rules.staleDays())))add(e,loan,"lastUpdatedAt","Record is stale (over "+rules.staleDays()+" days old)");if(loan.getSourceLoanId()!=null&&!loan.getSourceLoanId().isBlank()&&loans.findBySourceLoanId(loan.getSourceLoanId()).stream().anyMatch(x->!Objects.equals(x.getId(),loan.getId())))add(e,loan,"sourceLoanId","Duplicate loan ID found in a prior source record");if(loan.getBorrowerName()!=null&&loan.getPrincipalAmount()!=null&&loan.getOriginationDate()!=null&&loans.findByBorrowerNameAndPrincipalAmountAndOriginationDate(loan.getBorrowerName(),loan.getPrincipalAmount(),loan.getOriginationDate()).stream().anyMatch(x->!Objects.equals(x.getId(),loan.getId())))add(e,loan,"borrowerName","Suspicious duplicate borrower, amount, and origination-date combination");return e;}
 private void required(List<ValidationException> e,Loan l,String f,String v,String m){if(v==null||v.isBlank())add(e,l,f,m);} private void add(List<ValidationException> e,Loan l,String f,String m){String severity=(f.equals("sourceLoanId")||f.equals("principalAmount")||f.equals("currentBalance")||f.equals("maturityDate"))?"HIGH":f.equals("lastUpdatedAt")?"MEDIUM":"ERROR";e.add(ValidationException.builder().loan(l).fieldName(f).severity(severity).errorMessage(m).resolved(false).build());}
}
